edits.replacement:
.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1o (his #50, from the AAA judge of the Last Pour shot): THE DRINKS READ AS A MENU. Each drink was a line
   of body text with a small 40px INGEST box and its price floating apart from it. The name is 20px condensed caps now (the words
   are not changed, only drawn in caps), the price is large and sits against a 48px amber INGEST, and out of reach INGEST is a solid
   greyed button whose words can be read. */
#root #barmodal .plist .row{ min-height:84px; gap:16px; }
#root #barmodal .plist .row b{ font-family:var(--f-cond); font-size:20px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; }
#root #barmodal .plist .row .vl{ font-family:var(--f-cond); font-size:22px; font-weight:700; min-width:72px; text-align:right; }
#root #barmodal button[data-bz]{ min-height:48px; min-width:170px !important; font-size:17px; font-weight:700; letter-spacing:.12em;
  background:var(--acc); border-color:var(--acc); color:var(--acc-ink); }
#root #barmodal button[data-bz]:hover:not(:disabled){ background:#f7c25a; border-color:#f7c25a; color:var(--acc-ink); }
#root #barmodal button[data-bz]:disabled{ background:var(--ui-hover); border-color:var(--ui-line-hi) !important; color:var(--tx-2) !important; }

check:
{v:'VER',what:'his #50 (UI redesign ui5q1o, from the AAA judge of the Last Pour shot): a drink name is 19px or more in caps, its price 20px or more, and INGEST is at least 46px tall with a 16px label, amber when it can be bought and never in the faint third text colour',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], b, nm, pr, s;
   try{
     __topClear(); __hubEnter(); __station('bar','KeyE');
     b=document.querySelector('#barmodal button[data-bz]');
     if(!b||!b.getClientRects().length) return 'SKIP: the Last Pour did not open here';
     nm=b.parentNode.querySelector('b'); pr=b.parentNode.querySelector('.vl');
     if(nm){ s=getComputedStyle(nm); if(!(parseFloat(s.fontSize)>=19)||s.textTransform!=='uppercase') bad.push('a drink name is '+s.fontSize+' '+s.textTransform); }
     if(pr&&!(parseFloat(getComputedStyle(pr).fontSize)>=20)) bad.push('a drink price is '+getComputedStyle(pr).fontSize);
     s=getComputedStyle(b);
     if(!(parseFloat(s.minHeight)>=46)) bad.push('INGEST is held to '+s.minHeight);
     if(!(parseFloat(s.fontSize)>=16)) bad.push('INGEST is '+s.fontSize);
     if(!b.disabled&&s.backgroundColor!=='rgb(245, 183, 59)') bad.push('INGEST is not amber ('+s.backgroundColor+')');
     if(b.disabled&&s.color==='rgb(122, 118, 110)') bad.push('a greyed INGEST is in the faint third text colour');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
